<?php
get_header(); $map = function_exists('gc_ng_state_capitals') ? gc_ng_state_capitals() : array(); $state = isset($_GET['gc_state']) ? sanitize_text_field(wp_unslash($_GET['gc_state'])) : ''; $capital = isset($_GET['gc_capital']) ? sanitize_text_field(wp_unslash($_GET['gc_capital'])) : ''; $selected = null; if ($state) { $q = new WP_Query(array('post_type'=>'gc_chapter','post_status'=>'publish','posts_per_page'=>1,'meta_query'=>array(array('key'=>'gc_chapter_state','value'=>$state,'compare'=>'=')))); if ($q->have_posts()) { $q->the_post(); $selected = array('id'=>get_the_ID(),'title'=>get_the_title(),'url'=>get_permalink(),'capital'=>get_post_meta(get_the_ID(),'gc_chapter_capital',true) ?: ($map[$state] ?? ''),'whatsapp'=>get_post_meta(get_the_ID(),'gc_whatsapp_link',true),'organiser'=>get_post_meta(get_the_ID(),'gc_chapter_organiser',true)); wp_reset_postdata(); } } ?>
<main class="gc-interior gc-chapter-finder">
<section class="gc-page-hero gc-dark"><div class="gc-container"><span class="gc-kicker">Grassroots community</span><h1>Find your <em>chapter.</em></h1><p>Choose your state and capital to connect with the Game Changers community near you.</p></div></section>
<section class="gc-section"><div class="gc-container gc-narrow-form">
<form class="gc-location-form" method="get">
<div><label for="gc-state-filter">State</label><select id="gc-state-filter" name="gc_state" required><option value="">Select state</option><?php foreach($map as $st=>$cap): ?><option value="<?php echo esc_attr($st); ?>" <?php selected($state,$st); ?>><?php echo esc_html($st); ?></option><?php endforeach; ?></select></div>
<div><label for="gc-capital-filter">Capital</label><select id="gc-capital-filter" name="gc_capital"><option value="">Select capital</option><?php foreach($map as $st=>$cap): ?><option data-state="<?php echo esc_attr($st); ?>" value="<?php echo esc_attr($cap); ?>" <?php selected($capital,$cap); ?>><?php echo esc_html($cap); ?></option><?php endforeach; ?></select></div>
<button class="gc-button gc-button-green" type="submit">Find Chapter</button>
</form>
<?php if($selected): ?>
<div class="gc-location-result"><span class="gc-kicker gc-kicker-green">Chapter found</span><h2><?php echo esc_html($selected['title']); ?></h2><p class="gc-chapter-location"><?php echo esc_html($selected['state'] ?? $state); ?> · <?php echo esc_html($selected['capital']); ?></p><?php if($selected['organiser']): ?><p>Local organiser: <?php echo esc_html($selected['organiser']); ?></p><?php endif; ?><div class="gc-actions"><a class="gc-button gc-button-outline" href="<?php echo esc_url($selected['url']); ?>">View Chapter</a><?php if($selected['whatsapp']): ?><a class="gc-button gc-button-green" target="_blank" rel="noopener" href="<?php echo esc_url($selected['whatsapp']); ?>">Join on WhatsApp</a><?php endif; ?></div></div>
<?php elseif($state): ?><div class="gc-location-result"><h2>No chapter listed yet</h2><p>We have the <?php echo esc_html($state); ?> location recorded. You can start the chapter for this state.</p><a class="gc-button gc-button-green" href="<?php echo esc_url(gc_page_url('start-a-chapter')); ?>">Start a Chapter</a></div><?php endif; ?>
</div></section></main>
<script>(function(){var s=document.getElementById('gc-state-filter'),c=document.getElementById('gc-capital-filter');if(!s||!c)return;function sync(){var v=s.value;Array.prototype.forEach.call(c.options,function(o){if(!o.dataset.state)return;o.hidden=!!v&&o.dataset.state!==v;if(o.dataset.state===v)c.value=o.value;});}s.addEventListener('change',sync);sync();})();</script>
<?php get_footer(); ?>
